import{_ as a,o as r,c as e,al as d}from"./chunks/framework.BawR2jEz.js";const b=JSON.parse('{"title":"Роли","description":"Права доступа к разделам и действиям exDoc — матрица разрешений по группам пользователей OpenCart, пресеты, экспорт и импорт.","frontmatter":{"title":"Роли","description":"Права доступа к разделам и действиям exDoc — матрица разрешений по группам пользователей OpenCart, пресеты, экспорт и импорт."},"headers":[],"relativePath":"settings/roles.md","filePath":"settings/roles.md"}'),o={name:"settings/roles.md"};function n(l,t,i,h,s,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="роли" tabindex="-1">Роли <a class="header-anchor" href="#роли" aria-label="Permalink to &quot;Роли&quot;">​</a></h1><p>Права доступа к разделам и действиям exDoc в админ-панели.</p><h2 id="концепция" tabindex="-1">Концепция <a class="header-anchor" href="#концепция" aria-label="Permalink to &quot;Концепция&quot;">​</a></h2><p>Разрешения настраиваются <strong>на группу пользователей OpenCart</strong>, а не на отдельного человека. На вкладке перечислены все группы из вашего магазина; открыв группу, вы задаёте, что её участникам видно и что им можно делать. Чтобы изменить права конкретного сотрудника, переведите его в другую группу штатными средствами OpenCart.</p><p>Одна из групп считается <strong>суперадминской</strong> — у неё полный доступ, снять галочки нельзя. По умолчанию это группа с идентификатором <code>1</code>, то есть стандартный Administrator.</p><h2 id="матрица-разрешении" tabindex="-1">Матрица разрешений <a class="header-anchor" href="#матрица-разрешении" aria-label="Permalink to &quot;Матрица разрешений&quot;">​</a></h2><p>Права разложены по трём блокам, у каждого свой набор столбцов — потому что действия отличаются по смыслу.</p><h3 id="основные-сущности" tabindex="-1">Основные сущности <a class="header-anchor" href="#основные-сущности" aria-label="Permalink to &quot;Основные сущности&quot;">​</a></h3><p>Категории документов, документы, коллекции, рубрики, визуальные блоки, шаблоны.</p><table tabindex="0"><thead><tr><th>Столбец</th><th>Что разрешает</th></tr></thead><tbody><tr><td>Сайдбар</td><td>видеть пункт в левой панели навигации</td></tr><tr><td>Список</td><td>открывать список записей</td></tr><tr><td>Просмотр</td><td>открывать запись</td></tr><tr><td>Ред.</td><td>сохранять изменения</td></tr><tr><td>Доб.</td><td>создавать новые записи</td></tr><tr><td>Клон</td><td>копировать существующие</td></tr><tr><td>Экспорт</td><td>выгружать записи</td></tr><tr><td>Импорт</td><td>загружать записи</td></tr><tr><td>Удал.</td><td>удалять</td></tr></tbody></table><h3 id="системные" tabindex="-1">Системные <a class="header-anchor" href="#системные" aria-label="Permalink to &quot;Системные&quot;">​</a></h3><p>Настройки, поиск, лог, файловый менеджер, экспресс-настройки.</p><table tabindex="0"><thead><tr><th>Столбец</th><th>Что разрешает</th></tr></thead><tbody><tr><td>Сайдбар</td><td>видеть пункт в левой панели навигации</td></tr><tr><td>Меню</td><td>видеть пункт в верхнем меню</td></tr><tr><td>Просмотр</td><td>открывать раздел</td></tr><tr><td>Ред.</td><td>сохранять изменения</td></tr><tr><td>Замена</td><td>пользоваться заменой в поиске</td></tr></tbody></table><h3 id="быстрые-настроики" tabindex="-1">Быстрые настройки <a class="header-anchor" href="#быстрые-настроики" aria-label="Permalink to &quot;Быстрые настройки&quot;">​</a></h3><p>Палитры, схемы, элементы UI Kit, переменные, глобальные стили и скрипты, SVG-спрайты, глобальные компоненты, глобальные поля, пресеты полей.</p><table tabindex="0"><thead><tr><th>Столбец</th><th>Что разрешает</th></tr></thead><tbody><tr><td>Быстр.</td><td>открывать раздел в окне быстрых настроек</td></tr></tbody></table><p>Не у каждой сущности есть все столбцы своего блока: клетка появляется только там, где действие для этой сущности вообще существует. У настроек, например, нет ни «Меню», ни «Замены» — только «Сайдбар», «Просмотр» и «Ред.».</p><p>Рядом с группой показан счётчик — скольким сущностям из общего числа выдан хоть какой-то доступ.</p><h2 id="пресеты" tabindex="-1">Пресеты <a class="header-anchor" href="#пресеты" aria-label="Permalink to &quot;Пресеты&quot;">​</a></h2><p>Пресет — готовый набор галочек, который применяется к группе целиком. Применение заменяет текущие настройки группы, поэтому оно спрашивает подтверждение.</p><p>Встроенных три:</p><ul><li><strong>Полный доступ</strong> — все разрешения, какие есть у каждой сущности;</li><li><strong>Только просмотр</strong> — видимость в навигации плюс просмотр списков и записей, без изменений;</li><li><strong>Редактор</strong> — то же, что «Только просмотр», плюс редактирование и добавление. Ни удаления, ни клонирования, ни импорта-экспорта.</li></ul><p>Свой пресет создаётся из уже настроенной группы: <strong>Сохранить как пресет</strong> — и он встаёт рядом со встроенными. Пользовательские пресеты хранятся в настройках модуля и доступны всем администраторам.</p><h2 id="массовые-деиствия" tabindex="-1">Массовые действия <a class="header-anchor" href="#массовые-деиствия" aria-label="Permalink to &quot;Массовые действия&quot;">​</a></h2><p>Внутри группы: <strong>Выбрать всё</strong> и <strong>Снять всё</strong> — обе операции переписывают текущие галочки и потому подтверждаются.</p><h2 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h2><p>Права выгружаются в JSON: <strong>Экспорт</strong> — одна группа, <strong>Экспорт всех</strong> — сразу все. Результат копируется в буфер обмена.</p><p>При импорте exDoc предложит заодно сохранить принесённые права как пресет. Если в файле нет какой-то из сущностей — например, он снят с более старой версии модуля, — вы увидите предупреждение с их количеством: доступ к ним не назначится, и его нужно будет проставить руками.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./">Настройки</a> — остальные вкладки раздела</li><li><a href="./../log/">Лог</a> — журнал действий пользователей</li></ul>',30)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
